/* Ember: a personal, browser-local IELTS practice studio. */
(() => {
'use strict';
const E=window.Ember, A=window.CONTENT_A, B=window.CONTENT_B;
if(!E||!A||!B){document.getElementById('app-error').hidden=false;document.getElementById('app-error').textContent='学习内容未完整加载，请刷新页面。';return;}
const days=[...A.days,...B.days].sort((a,b)=>a.id-b.id), words=[...A.words,...B.words], grammar=[...A.grammar,...B.grammar];
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths={today:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',plan:'M5 5h14v16H5z M8 2v6 M16 2v6 M5 10h14',bank:'M4 4h7v16H4z M14 4h6v16h-6z',memory:'M12 3a7 7 0 0 0-4 13v4h8v-4a7 7 0 0 0-4-13z M9 23h6 M9 10h6',stories:'M3 4c4-1 7 0 9 2 2-2 5-3 9-2v16c-4-1-7 0-9 2-2-2-5-3-9-2z M12 6v16',official:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 12l3 3 5-6',progress:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',listening:'M4 14v-3a8 8 0 0 1 16 0v3 M4 12h3v8H4z M17 12h3v8h-3z',reading:'M4 3h16v18H4z M8 7h8 M8 11h8 M8 15h5',writing:'M4 20l4-1L20 7l-3-3L5 16z M14 7l3 3',speaking:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v4 M8 23h8',grammar:'M3 19L9 4l6 15 M5 14h8 M16 10h6 M19 7v12',review:'M3 10a9 9 0 1 1 2 9 M3 4v6h6 M12 7v6l4 2',arrow:'M4 12h16 M14 6l6 6-6 6',check:'M5 12l4 4L19 6',play:'M8 4l12 8-12 8z',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18z M12 7v6l4 2'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[n]||iconPaths.bank}"/></svg>`;
const names={today:'今日学习',plan:'学习日历',bank:'四项题库',memory:'词汇复习',stories:'故事精读',official:'真题与样题',progress:'学习记录',settings:'学习设置',listening:'听力 Listening',reading:'阅读 Reading',writing:'写作 Writing',speaking:'口语 Speaking',grammar:'语法热身',review:'词汇与复习'};
const today=()=>E.today();
const dayIndex=()=>Math.max(1,Math.floor((Date.parse(today())-Date.parse(E.getState().startDate))/86400000)+1);
let selectedDay=Math.min(14,dayIndex()), view='today', activeSkill='reading', bankFilter='all', questionSet=[], reviewQueue=[], reviewIndex=0, reviewCorrect=0, reviewAnswered=false, memoryFilter='all';
let timerRunning=false,timerSeconds=Math.min(3600,Math.round(E.day().minutes*60)),timerStart=0,timerTick=0, timerDate=today();
let recorder=null,mediaStream=null,recordTick=null,recordStarted=0,activeRecordKey='',lastRecordBlob=null,recordUrl=null,speakCountdown=null;
const selected=()=>days.find(d=>d.id===selectedDay)||days[0];
const dateFor=d=>E.addDays(E.getState().startDate,d-1);
const prettyDate=d=>new Date(d+'T12:00:00+08:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long',timeZone:'Asia/Shanghai'});
const shortDate=d=>d.slice(5).replace('-','/');
const getWords=d=>d.vocabIds.map(id=>words.find(w=>w.id===id)).filter(Boolean);
const grammarMap={1:['g20','g07','g10'],2:['g01','g03','g05','g06'],3:['g08','g09','g11','g12'],4:['g13','g14','g15','g16'],5:['g17','g18','g19'],6:['g04','g21','g22','g24'],7:['g02','g07','g23','g24'],8:['gb01','gb02','gb03'],9:['gb04','gb13','g08'],10:['gb05','gb06','gb14'],11:['gb07','gb08','g15'],12:['gb09','gb10','g06'],13:['gb11','gb12','gb16'],14:['gb02','gb15','gb16']};
const lessonVocabulary=()=>{const st=E.getState();return words.filter(w=>selected().vocabIds.includes(w.id)||st.words[w.id]?.firstSeen===today()||st.words[w.id]?.due<=today()).slice(0,16);};
function variedOptions(q){return q.options.map((v,i)=>({v,score:[...q.id+today()+i].reduce((a,c)=>((a*33)^c.charCodeAt(0))>>>0,2166136261)})).sort((a,b)=>a.score-b.score).map(x=>x.v);}
function reviewBridge(){const list=E.dueWords(words).slice(0,3);if(!list.length)return '';return '<section class="panel"><h3>到期词汇填空</h3><p class="small-text muted">主课文以主题推进；额外到期词通过不同例句补充复习。先尝试填空，再展开核对。</p>'+list.map(w=>'<p class="article">'+esc(w.cloze)+'</p><details class="details"><summary>核对这个词</summary><p>'+esc(w.word)+' — '+esc(w.meaning)+'</p><p>'+esc(w.example)+'</p></details>').join('')+'</section>';}
const done=k=>E.isComplete(`d${selectedDay}:${k}`);
const skills=['review','grammar','listening','reading','writing','speaking'];
const taskTimes=d=>({review:10,grammar:5,listening:d.focus==='listening'?15:10,reading:d.focus==='reading'?15:10,writing:d.focus==='writing'?15:10,speaking:d.focus==='speaking'?15:10});
const complete=k=>{E.complete(`d${selectedDay}:${k}`);toast(E.getLastError()?'已在当前会话记录，但保存失败，请导出备份':'已记录完成，进度已保存');showStorageError();updateNav();};
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(t.timeout);t.timeout=setTimeout(()=>t.classList.remove('show'),3500);}
function showStorageError(){if(E.getLastError()){const el=$('#app-error');el.hidden=false;el.textContent=E.getLastError()+' 请在设置中导出备份。';}}
function heading(title,sub,eyebrow='',right=''){return `<div class="heading"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${right}</div>`;}
function empty(title,desc){return `<div class="empty-state">${icon('memory')}<h3>${esc(title)}</h3><p>${esc(desc)}</p></div>`;}
function updateNav(){const due=E.dueWords(words).length;$('#nav').innerHTML=['today','plan','bank','memory','stories','official','progress'].map(n=>`<button class="nav-item ${view===n||(view==='lesson'&&n==='bank')||(view==='review'&&n==='memory')?'active':''}" data-action="nav" data-view="${n}">${icon(n)}<span>${names[n]}</span>${n==='memory'&&due?`<span class="badge-count">${due}</span>`:''}</button>`).join('');$('#breadcrumb').textContent='Ember / '+(names[view]||names[activeSkill]||'每日练习');}
function navigate(v,day,skill){if(recorder?.state==='recording')stopRecording();stopSpeech();clearInterval(speakCountdown);if(day)selectedDay=Number(day);if(skill)activeSkill=skill;view=v;$('#sidebar').classList.remove('open');render();window.scrollTo(0,0);history.replaceState(null,'','#'+v);}
function render(){stopWordAudio();updateNav();const main=$('#main');const pages={today:renderToday,plan:renderPlan,bank:renderBank,memory:renderMemory,stories:renderStories,official:renderOfficial,progress:renderProgress,settings:renderSettings,lesson:renderLesson,review:renderReview};main.innerHTML=(pages[view]||renderToday)();if(view==='lesson')mountLesson();if(view==='review')mountReview();if(view==='memory')filterWords();showStorageError();}
function renderToday(){
const d=selected(),stats=E.stats(),current=skills.filter(done).length,newSet=E.newWords(words),due=E.dueWords(words),t=taskTimes(d);
const quantity=s=>s==='review'?'新词 '+newSet.length+' 个 · 到期 '+due.length+' 个':s==='grammar'?(grammarMap[d.id]||[]).length+' 题':s==='reading'||s==='listening'?d[s].questions.length+' 题':s==='writing'?'至少 '+d.writing.minWords+' 词':'1 次录音与复盘';
return heading('今日学习',prettyDate(today()),'', '<span class="pill">目标 IELTS <strong>'+esc(E.getState().settings.target)+'</strong> · 每日 60 分钟</span>')+
'<section class="daily-overview"><div><span class="date-label">第 '+selectedDay+' 天</span><h2>'+esc(d.title)+'</h2><p>重点：'+names[d.focus]+' · 6 项任务 · 60 分钟</p></div><button class="btn primary" data-action="start-day"'+(current===6?' disabled':'')+'>'+(current===6?'今日任务已完成':current?'继续学习':'开始学习')+' '+icon('arrow')+'</button></section>'+
'<div class="stat-row"><div class="stat-card"><div class="stat-icon">'+icon('memory')+'</div><div><div class="stat-number">'+newSet.length+' <small>个</small></div><p>待学新词</p></div></div><div class="stat-card"><div class="stat-icon">'+icon('review')+'</div><div><div class="stat-number">'+due.length+' <small>个</small></div><p>到期复习</p></div></div><div class="stat-card"><div class="stat-icon">'+icon('check')+'</div><div><div class="stat-number">'+current+'<small> / 6</small></div><p>任务完成 · 连续学习 '+stats.streak+' 天</p></div></div></div>'+
'<div class="dashboard-grid"><section><div class="section-head"><h2>任务清单</h2><button class="text-link" data-action="nav" data-view="plan">14 天学习计划 ↗</button></div><div class="week-strip">'+days.slice(selectedDay>7?7:0,selectedDay>7?14:7).map(x=>'<button class="day-chip '+(x.id===selectedDay?'active':'')+'" data-action="select-day" data-day="'+x.id+'">DAY '+String(x.id).padStart(2,'0')+'<strong>'+dateFor(x.id).slice(8)+'</strong><span>'+['周日','周一','周二','周三','周四','周五','周六'][new Date(dateFor(x.id)+'T12:00:00Z').getUTCDay()]+'</span><i></i></button>').join('')+'</div>'+
(selectedDay!==dayIndex()?'<p class="small-text muted">正在查看第 '+selectedDay+' 天内容，练习记录计入今天。</p>':'')+
'<div class="task-list">'+skills.map((s,i)=>'<button class="task" data-action="task" data-skill="'+s+'"><span class="task-icon">'+icon(s)+'</span><span><strong>'+String(i+1).padStart(2,'0')+' &nbsp; '+names[s]+'</strong><small>'+esc(quantity(s))+'</small></span><span class="task-meta">'+(done(s)?'<span class="check">✓</span>':t[s]+' 分钟 &nbsp; ↗')+'</span></button>').join('')+'</div></section>'+
'<aside><div class="section-head"><h2>今日词汇</h2><span>'+newSet.length+' 个待学</span></div><div class="side-card"><p>点击单词听发音，首次学习后次日复习。</p><div class="word-chips">'+newSet.slice(0,6).map(w=>'<button type="button" class="word-chip word-chip-audio" data-action="speak-word" data-id="'+w.id+'" aria-label="播放 '+esc(w.word)+' 的发音">'+esc(w.word)+' '+icon('listening')+'</button>').join('')+(newSet.length?'':'<span class="small-text">今日新词已学完。</span>')+'</div><button class="text-link" data-action="nav" data-view="memory">词汇学习与复习 '+icon('arrow')+'</button></div><div class="side-card note"><h3>复习安排</h3><p>拼写、填空、听音、造句轮换练习。根据答题情况调整间隔。</p><div class="memory-path">'+['1 天','3 天','7 天','14 天'].map(x=>'<div><i></i>'+x+'</div>').join('')+'</div></div></aside></div>';
}
function renderPlan(){return heading('14 天学习计划','每日 60 分钟，四项技能轮换重点。','')+`<div class="notice">每天：词汇复习 10 分钟＋语法 5 分钟＋重点技能 15 分钟＋其他三项各 10 分钟。第 7、14 天做迁移复盘。长篇考试训练放在「真题与样题」，可分日完成；整套限时模拟需要另外预留完整时段。</div><div class="card-grid">${days.map(d=>`<article class="lesson-card ${d.id===Math.min(dayIndex(),14)?'current':''}"><div class="meta"><span class="day-index">${String(d.id).padStart(2,'0')}</span><span>${shortDate(dateFor(d.id))} · 60 min</span></div><h3>${esc(d.title)}</h3><p>${esc(d.subtitle)}</p><span class="skill-note">重点 · ${names[d.focus]}</span><button class="btn small" data-action="select-day" data-day="${d.id}">${d.id>dayIndex()?'预览训练':'打开训练'} ${icon('arrow')}</button></article>`).join('')}</div><section class="panel" style="margin-top:24px"><h3>计划说明</h3><p class="small-text">这是适合你当前阶段的实践安排：先短练建立准确性，再把同一批词汇放进不同技能与故事情境中。回忆练习和分散学习有较好的研究支持；这里的具体天数与配比是可调整的学习设计，并非保证提分的公式。</p><a class="inline-source" href="https://www.psychologicalscience.org/journals/pspi/1529100612453266/" target="_blank" rel="noopener noreferrer">研究依据：Dunlosky 等，2013 · Effective Learning Techniques ↗</a><p class="small-text muted">完成首轮后，可从错题、到期词汇和官方题继续练习。当前内置 14 天内容，不会自动生成未经核验的新闻或新真题。</p></section>`;}
function renderBank(){return heading('四项题库',`${days.reduce((n,d)=>n+d.reading.questions.length+d.listening.questions.length,0)+grammar.length} 道客观题 · 28 组写作与口语任务 · 原创基础训练`,'')+`<div class="chips">${['all','listening','reading','writing','speaking','grammar'].map(s=>`<button class="chip ${bankFilter===s?'active':''}" data-action="bank-filter" data-filter="${s}">${s==='all'?'全部技能':names[s]}</button>`).join('')}</div><div class="card-grid">${days.map(d=>`<article class="lesson-card"><div class="meta"><span>DAY ${String(d.id).padStart(2,'0')}</span><span>${esc(d.theme)}</span></div><h3>${esc(d.title)}</h3><p>${esc(bankFilter==='all'?d.subtitle:bankFilter==='grammar'?d.grammar.title:d[bankFilter].title)}</p><div class="task-actions">${(bankFilter==='all'?['listening','reading','writing','speaking']:[bankFilter]).map(s=>`<button class="btn small" data-action="lesson" data-day="${d.id}" data-skill="${s}">${names[s].split(' ')[0]} ↗</button>`).join('')}</div></article>`).join('')}</div>`;}
function makeQuestion(q,i){return `<fieldset class="question" data-q="${esc(q.id)}"><legend><span class="q-number">${String(i+1).padStart(2,'0')}</span>${esc(q.prompt)}</legend>${q.type==='choice'?variedOptions(q).map((o,j)=>`<label class="option"><input type="radio" name="q${i}" value="${esc(o)}" required><span>${esc(o)}</span></label>`).join(''):`<label class="sr-only" for="answer-${i}">${esc(q.prompt)}</label><input class="answer-input" id="answer-${i}" name="q${i}" autocomplete="off" placeholder="输入英文答案" required maxlength="500">`}<div class="q-feedback" aria-live="polite"></div></fieldset>`;}
function quizHTML(qs,skill){questionSet=qs;return `<form id="quiz-form" data-skill="${skill}"><div id="quiz-result" aria-live="polite"></div>${qs.map(makeQuestion).join('')}<button class="btn primary" type="submit">提交并查看解析 ${icon('arrow')}</button><button type="button" class="btn secondary" style="margin-left:7px" data-action="retry-quiz">重新练习</button></form>`;}
function highlighted(text){let safe=esc(text);const candidates=[...new Set([...getWords(selected()).map(w=>w.word),...E.dueWords(words).map(w=>w.word)])].filter(w=>/^[a-z -]+$/i.test(w)).sort((a,b)=>b.length-a.length);if(candidates.length)safe=safe.replace(new RegExp(`\\b(${candidates.map(w=>w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')})\\b`,'gi'),'<mark>$1</mark>');return safe;}
function renderLesson(){const d=selected(),s=activeSkill;let sub=`DAY ${String(d.id).padStart(2,'0')} · ${d.title} · 原创基础训练`;if(s==='official-speaking')return renderOfficialSpeaking();let result=heading(names[s],sub,'',`<button class="btn small" data-action="nav" data-view="today">← 今日任务</button>`);
if(s==='reading'){return result+`<div class="training-layout"><article class="panel sticky"><span class="kicker">ORIGINAL STORY · ${d.reading.text.split(/\s+/).length} WORDS</span><h2 class="article-title">${esc(d.reading.title)}</h2><div class="article">${highlighted(d.reading.text)}</div><p class="small-text muted">暖黄色标记：今日或到期词汇。先通读，再寻找答案证据。</p><details class="details"><summary>读完后，用自己的话总结</summary><p>合上文章，写两句总结，并使用至少两个标记词。这个步骤训练迁移，不计入客观题正确率。</p><textarea class="writing-box" style="min-height:120px" data-draft="summary-${d.id}" aria-label="文章总结" placeholder="In this story…">${esc(E.getDraft('summary-'+d.id))}</textarea></details></article><section class="panel">${quizHTML(d.reading.questions,'reading')}</section><div class="full-width">${reviewBridge()}</div></div>`;}
if(s==='listening'){return result+`<div class="training-layout"><section class="sticky"><div class="audio-panel"><h3>${esc(d.listening.title)}</h3><div class="audio-wave" aria-hidden="true">${Array.from({length:52},(_,i)=>`<span style="height:${8+(i*17%36)}px"></span>`).join('')}</div><audio id="lesson-audio" controls preload="metadata" src="audio/day-${d.id}.wav"></audio><div class="audio-controls"><label for="audio-speed" class="small-text">语速</label><select id="audio-speed"><option value=".8">0.8×</option><option value="1" selected>1.0×</option><option value="1.2">1.2×</option></select><button class="btn small secondary" data-action="speak-listening">备用朗读</button><button class="btn small secondary" data-action="stop-speech">停止朗读</button></div><p class="small-text muted">原创练习 · 英语合成语音。第一遍不看原文，核对后再听；正式考试音频在官方练习中。</p></div><div class="panel"><h3>听之前，先预测</h3><p class="small-text muted">浏览问题：需要的是数字、原因、人物还是一个动作？听完后再提交答案。</p><details class="details"><summary>听完再展开原文</summary><div class="article">${esc(d.listening.transcript)}</div></details></div></section><section class="panel">${quizHTML(d.listening.questions,'listening')}</section></div>`;}
if(s==='grammar'){const qs=(grammarMap[d.id]||[]).map(id=>grammar.find(q=>q.id===id)).filter(Boolean);return result+`<div class="training-layout"><section class="panel"><h2>${esc(d.grammar.title)}</h2><p class="small-text">${esc(d.grammar.rule)}</p>${d.grammar.examples.map(x=>`<div class="grammar-example">${esc(x)}</div>`).join('')}<p class="small-text muted">先判断时间、主语和句式，再选择动词。今天热身也会穿插之前学过的结构。</p></section><section class="panel">${quizHTML(qs,'grammar')}</section></div>`;}
if(s==='writing'){return result+`<div class="training-layout"><section class="panel"><h2>${esc(d.writing.title)}</h2><div class="prompt">${esc(d.writing.prompt)}</div><p class="small-text muted">建议 ${d.writing.minWords}–${d.writing.minWords+40} 词。这是段落基础训练，完整考试 Task 1 / Task 2 请进入官方题库。</p><h3 style="margin-top:25px">参考词汇</h3><div class="word-chips">${lessonVocabulary().map(w=>`<button type="button" class="word-chip word-chip-audio" data-action="speak-word" data-id="${w.id}" aria-label="播放 ${esc(w.word)} 的发音">${esc(w.word)} ${icon('listening')}</button>`).join('')}</div><p class="small-text muted">自然使用 2–3 个合适的词，不必为了数量强行加入。</p><details class="details"><summary>写完后对照示例</summary><div class="article">${esc(d.writing.model)}</div><p class="small-text muted">原创参考表达，不是官方评分范文。</p></details></section><section class="panel"><div class="inline-row between"><h3>你的草稿</h3><span class="date-label">输入时自动保存</span></div><textarea id="writing-draft" class="writing-box" data-draft="writing-${d.id}" spellcheck="true" lang="en" aria-label="写作草稿" placeholder="Start with one clear idea…">${esc(E.getDraft('writing-'+d.id))}</textarea><div class="writing-footer"><span id="word-count">0 words</span><span id="draft-status">本机草稿</span></div><button class="btn primary" data-action="writing-feedback">检查表达 ${icon('arrow')}</button><div id="writing-feedback" aria-live="polite"></div><div class="checklist">${d.writing.checklist.map((c,i)=>`<label><input type="checkbox" class="writing-check" id="wc${i}">${esc(c)}</label>`).join('')}</div><button class="btn secondary wide" data-action="finish-writing">完成检查并记录</button><p class="small-text muted">表达检查仅提示词数和部分常见错误；内容、逻辑与 IELTS 分数需要人工反馈。</p></section></div>`;}
if(s==='speaking'){return result+speakingWorkspace(d.speaking,'speaking-'+d.id,false);}
return result;}
function speakingWorkspace(task,key,official){return `<div class="training-layout"><section class="panel"><span class="kicker">${official?'OFFICIAL SAMPLE · PART 2':'口语练习'}</span><h2>${esc(task.title)}</h2><div class="prompt">${esc(task.prompt)}</div><ul class="feedback-list">${task.cues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="inline-row"><button class="btn small" data-action="prep-timer">准备 1 分钟</button><button class="btn small secondary" data-action="speak-timer">表达 2 分钟</button><span id="speaking-countdown" class="small-text"></span></div><label class="field-label" style="margin-top:25px" for="speaking-notes">只记关键词，避免照读全文</label><textarea id="speaking-notes" class="writing-box" style="min-height:130px" data-draft="notes-${key}" placeholder="Who? What happened? Why?" aria-label="口语笔记">${esc(E.getDraft('notes-'+key))}</textarea>${task.model?`<details class="details"><summary>录完第一遍后，查看参考思路</summary><div class="article">${esc(task.model)}</div></details>`:''}${official?'<p class="small-text"><a href="https://ielts.org/cdn/ielts-downloadable-assets/ielts-sample-tests/ielts-speaking-sample-tasks-2023.pdf" target="_blank" rel="noopener noreferrer">来源：IELTS 官方公开 Speaking 样题，第 5 页 ↗</a></p>':''}</section><section class="panel"><div class="record-area"><button id="record-button" class="record-button" data-action="record" data-key="${key}" aria-label="开始录音">${icon('speaking')}</button><div id="record-clock" class="record-clock">00:00</div><p id="record-status">点击录音，允许使用麦克风</p><div id="record-playback"></div></div><h3>回听时，只关注这三件事</h3><div class="checklist"><label><input class="speaking-check" type="checkbox">我回答了题目，并给出具体例子。</label><label><input class="speaking-check" type="checkbox">我检查了过去时、主谓一致与长停顿。</label><label><input class="speaking-check" type="checkbox">我找到了下一次要改进的一处表达。</label></div><label class="field-label" for="reflection">记录一次改进</label><input id="reflection" class="field" data-draft="reflection-${key}" value="${esc(E.getDraft('reflection-'+key))}" placeholder="例如：did 后使用 want，不用 wanted。"><button class="btn secondary wide" style="margin-top:16px" data-action="finish-speaking" data-key="${key}">完成回听与复盘</button><p class="small-text muted">录音保存在当前浏览器，可回放及下载。不会自动评分或上传。麦克风不可用时，可自行朗读并填写复盘。</p></section></div>`;}
function mountLesson(){if(activeSkill==='writing')updateWordCount();if(['speaking','official-speaking'].includes(activeSkill)){activeRecordKey=activeSkill==='official-speaking'?'official-speaking':'speaking-'+selectedDay;loadRecording(activeRecordKey);}const a=$('#lesson-audio');if(a){a.addEventListener('play',()=>$('.audio-wave')?.classList.add('playing'));a.addEventListener('pause',()=>$('.audio-wave')?.classList.remove('playing'));a.addEventListener('ended',()=>$('.audio-wave')?.classList.remove('playing'));a.addEventListener('error',()=>toast('音频未能加载，可使用备用朗读或稍后重试'));}}
function submitQuiz(form){const fd=new FormData(form);let count=0;questionSet.forEach((q,i)=>{const given=String(fd.get('q'+i)||''),correct=E.checkAnswer(given,q.answer,q.accepted);E.answer(q.id,given,correct,form.dataset.skill);if(correct)count++;const el=form.querySelector(`[data-q="${CSS.escape(q.id)}"]`);el.classList.remove('correct','incorrect');el.classList.add(correct?'correct':'incorrect');$('.q-feedback',el).innerHTML=`<div class="feedback ${correct?'':'wrong'}"><strong>${correct?'✓ 回答正确':'再看一眼 · 正确答案：'+esc(q.answer)}</strong>${esc(q.explanation)}</div>`;});if(form.dataset.reviewOnly!=='true')complete(form.dataset.skill);$('#quiz-result').innerHTML=`<div class="result-banner">本次答对 <strong>${count} / ${questionSet.length}</strong>。${count===questionSet.length?'接下来换一种情境使用它。':'请先读解析，再回到原文或音频寻找证据。错题已加入学习记录。'}</div>`;$('#quiz-result').scrollIntoView({behavior:'smooth',block:'center'});}
function updateWordCount(){const t=$('#writing-draft');if(!t)return;const count=wordCount(t.value);$('#word-count').textContent=count+' words';}
function wordCount(text){return (String(text).match(/[A-Za-z]+(?:['’-][A-Za-z]+)*/g)||[]).length;}
function writingFeedback(){const text=$('#writing-draft').value,n=wordCount(text),min=selected().writing.minWords;if(!n){toast('先写下你的想法，再检查表达');return;}const hints=[];const rules=[[/\bthey wants\b/i,'they 后的现在时用 want；过去时用 wanted。'],[/\b(?:did|didn[’']t)\s+(?:(?:I|you|we|they|he|she|it|the clients?|my clients?)\s+)?(?:wanted|wants|needed|needs)\b/i,'did / didn’t 后用动词原形：want / need。'],[/\bdecided to (?:learning|improving|changing)\b/i,'decided to 后用原形：learn / improve / change。'],[/\bknowledges\b/i,'knowledge 不可数，不加复数 -s。'],[/\ba interior\b/i,'interior 以元音音素开头：an interior designer。'],[/\bmaterials has\b/i,'materials 是复数，应使用 have。'],[/\bbecause (?:that|it) very\b/i,'because 后需要完整句子：because it is very important…'],[/\b(?:conmunicate|porffessional|unexpectly|knowleges|tarch)\b/i,'检查拼写：communicate / professional / unexpectedly / knowledge；表达「学习借鉴」可用 learn from。']];for(const [re,hint] of rules)if(re.test(text))hints.push(hint);if(n<min)hints.push(`当前 ${n} 词。再补充一个原因或例子，达到本次 ${min} 词的练习目标。`);if(!/[.!?]/.test(text))hints.push('使用句号分隔完整想法，避免把所有内容写成一个长句。');const used=lessonVocabulary().filter(w=>new RegExp(`\\b${w.word}\\b`,'i').test(text));$('#writing-feedback').innerHTML=`<div class="feedback"><strong>表达检查 · ${n} words</strong>${hints.length?`<ul class="feedback-list">${hints.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'未发现当前规则覆盖的常见错误。继续检查意思、时态和衔接；这不代表全文没有错误。'}<p>今日词汇使用：${used.length?used.map(w=>esc(w.word)).join(' · '):'暂未识别到；只在语境适合时使用。'}</p></div>`;}
function renderMemory(){const due=E.dueWords(words),fresh=E.newWords(words),st=E.getState();return heading('词汇复习','每天先复习，再认识新词。点击单词旁的耳机听发音，详情中可慢速跟读。','',`<button class="btn primary" data-action="begin-review">开始词汇练习 ${icon('arrow')}</button>`)+`<div class="stat-row"><div class="stat-card"><div><div class="stat-number">${due.length}<small> 个</small></div><p>到期词 · 优先复习</p></div></div><div class="stat-card"><div><div class="stat-number">${fresh.length}<small> 个</small></div><p>今日剩余新词 · 默认 6 个</p></div></div><div class="stat-card"><div><div class="stat-number">${Object.keys(st.words).length}<small> / ${words.length}</small></div><p>已接触词汇 · 不等于全部掌握</p></div></div></div><div class="notice">按前一天的回忆结果调整：完成至少 5 个词且正确率 ≥90%，增加 2 个新词（最多 12）；低于 70%，降至 3 个；到期词超过 12 个，暂停新词。首次学习后次日复习，再逐步间隔 3 / 7 / 14 / 30 天。当天重复答题不增加记忆等级。</div><div class="search-row"><input id="word-search" class="field" placeholder="搜索英文或中文释义" aria-label="搜索词汇"><select id="word-filter" style="max-width:160px" aria-label="筛选词汇"><option value="all">全部词汇</option><option value="due">到期复习</option><option value="learned">已接触</option><option value="new">尚未学习</option></select></div><div class="panel" style="overflow-x:auto"><table class="word-table"><thead><tr><th>WORD</th><th>中文意思</th><th class="optional">下次复习</th><th>状态</th><th></th></tr></thead><tbody id="word-table-body"></tbody></table></div>`;}
function filterWords(){const query=($('#word-search')?.value||'').toLowerCase(),filter=$('#word-filter')?.value||'all',st=E.getState();const list=words.filter(w=>{const learned=st.words[w.id];return (w.word+' '+w.meaning).toLowerCase().includes(query)&&(filter==='all'||filter==='due'&&learned&&learned.due<=today()||filter==='learned'&&learned||filter==='new'&&!learned);});$('#word-table-body').innerHTML=list.map(w=>{const r=st.words[w.id];return `<tr><td><div class="word-title-row">${esc(w.word)}<button type="button" class="word-audio-button" data-action="speak-word" data-id="${w.id}" aria-label="播放 ${esc(w.word)} 的发音" title="播放美式发音">${icon('listening')}</button></div></td><td>${esc(w.meaning)}</td><td class="optional">${r?esc(r.due):'—'}</td><td><span class="word-status ${r&&r.due<=today()?'due':''}">${r?(r.due<=today()?'待复习':'已接触 · '+r.reviews+' 次'):'新词'}</span></td><td><button class="text-link" data-action="word-detail" data-id="${w.id}" aria-label="查看 ${esc(w.word)}">查看 ↗</button></td></tr>`;}).join('')||'<tr><td colspan="5">没有匹配的词汇。</td></tr>';}
function beginReview(){reviewQueue=[...E.dueWords(words),...E.newWords(words)].slice(0,12).map(w=>({...w,isNew:!E.getState().words[w.id],reviewMode:E.getWordMode(w.id)}));reviewIndex=0;reviewCorrect=0;reviewAnswered=false;if(!reviewQueue.length&&Object.keys(E.day().wordReviews||{}).length)E.complete(`d${selectedDay}:review`);navigate('review');}
function renderReview(){const base=heading('词汇练习','每轮最多 12 个词，先复习再学新词；余下词汇留在队列中，可分轮完成。','',`<button class="btn small" data-action="nav" data-view="memory">← 词汇复习</button>`);if(!reviewQueue.length)return base+`<div class="panel">${empty('今天的词汇任务已完成','到期词会在下一个学习日出现。现在去故事里使用它们。')}<button class="btn secondary wide" data-action="nav" data-view="stories">去故事精读</button></div>`;if(reviewIndex>=reviewQueue.length){E.complete(`d${selectedDay}:review`);return base+`<div class="end-card"><h2>本轮已完成</h2><p>本轮完成 ${reviewQueue.length} 个词，${reviewCorrect} 个回忆正确或自评会用。仍有 ${E.dueWords(words).length} 个词待复习。</p><p class="small-text muted">错误词次日再次出现；成功词根据阶段进入下一次复习。</p><button class="btn primary" data-action="task" data-skill="grammar">继续语法热身 ${icon('arrow')}</button></div>`;}
const w=reviewQueue[reviewIndex],mode=w.reviewMode;let question=mode===0?`<div class="recall-prompt">${esc(w.meaning)}</div><p class="small-text muted">写出对应英文词汇。${w.phonetic?'音标提示：'+esc(w.phonetic):''}</p>`:mode===1?`<div class="recall-prompt">${esc(w.cloze)}</div><p class="small-text muted">用一个合适的词补全语境。</p>`:mode===2?`<div class="recall-prompt">听音，写出这个词。</div><button type="button" class="btn secondary" data-action="speak-word" data-id="${w.id}">${icon('listening')} 播放词汇</button>`:`<div class="recall-prompt">用 ${esc(w.word)} 写一个新句子。</div><p class="small-text muted">${esc(w.meaning)} · 换成你自己的工作或生活情境。至少 6 个英文词。</p>`;
return base+`<section class="panel review-card"><div class="inline-row between"><span class="kicker">${['主动回忆 / RECALL','语境填空 / CONTEXT','听音拼写 / LISTEN','表达迁移 / APPLY'][mode]}</span><span class="small-text muted">${reviewIndex+1} / ${reviewQueue.length} · ${w.isNew?'新词':'到期复习'}</span></div><div class="review-progress"><div style="width:${reviewIndex/reviewQueue.length*100}%"></div></div>${w.isNew?`<details class="details" style="margin:0 0 20px" open><summary>初次认识：先读例句，再合上回忆</summary><div class="word-display">${esc(w.word)}</div><div class="phonetic">${esc(w.phonetic)} · ${esc(w.pos)}</div>${wordAudioControls(w)}<p>${esc(w.meaning)}</p><p class="article">${esc(w.example)}</p><button class="btn small" type="button" data-action="close-word-card">合上学习卡</button></details>`:''}<form id="review-form">${question}<label class="sr-only" for="review-answer">你的答案</label><input id="review-answer" class="answer-input" style="margin:20px 0" autocomplete="off" placeholder="${mode===3?'Write your own sentence…':'输入英文答案'}" required maxlength="1000"><div id="review-feedback" aria-live="polite"></div><button class="btn primary" type="submit">${mode===3?'对照例句并自评':'检查答案'}</button></form><div id="review-next" class="task-actions"></div></section>`;}
function mountReview(){}
function submitReview(){if(reviewAnswered)return;const w=reviewQueue[reviewIndex],value=$('#review-answer').value.trim();if(!value)return;if(w.reviewMode===3){if(wordCount(value)<6||!new RegExp(`\\b${w.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}\\b`,'i').test(value)){toast('请写至少 6 个英文词，并包含目标词 '+w.word);return;}$('#review-feedback').innerHTML=`<div class="feedback"><strong>参考语境</strong>${esc(w.example)}<p>你的句子是否意思清楚、词性正确？此题由你自评，系统不判定语义正确性。</p></div>`;$('#review-next').innerHTML='<button class="btn secondary" data-action="rate-word" data-correct="false">还不熟悉，明天再练</button><button class="btn primary" data-action="rate-word" data-correct="true">对照后确认会用</button>';return;}const correct=E.checkAnswer(value,w.answer||w.word,[w.word]);rateWord(correct,value);}
function rateWord(correct,given){if(reviewAnswered)return;const w=reviewQueue[reviewIndex];reviewAnswered=true;E.reviewWord(w.id,correct,undefined,{given:given||$('#review-answer').value,selfRated:w.reviewMode===3});if(reviewIndex===reviewQueue.length-1)E.complete(`d${selectedDay}:review`);E.setDraft('word-sentence-'+w.id,$('#review-answer').value);if(correct)reviewCorrect++;$('#review-feedback').innerHTML=`<div class="feedback ${correct?'':'wrong'}"><strong>${correct?'✓ 已记录':'再认识一次：'+esc(w.word)}</strong>${esc(w.meaning)}<p>${esc(w.example)}</p>${wordAudioControls(w)}<span class="small-text">下次复习：${E.getState().words[w.id].due}</span></div>`;$('#review-form button[type="submit"]').disabled=true;$('#review-next').innerHTML='<button class="btn primary" data-action="next-word">下一个词 →</button>';updateNav();}
function renderStories(){return heading('故事精读','阅读故事，完成练习并复习标记词汇。','')+`<div class="notice">14 篇原创练习故事，并非新闻报道。暖黄色会标出当天及到期词汇。读完后做理解题，再用旧词写两句新总结。</div><div class="card-grid">${days.map(d=>`<article class="lesson-card"><div class="meta"><span class="day-index">${String(d.id).padStart(2,'0')}</span><span>${d.reading.text.split(/\s+/).length} words</span></div><h3 style="font-family:var(--serif);font-size:21px">${esc(d.reading.title)}</h3><p>${esc(d.subtitle)}</p><div class="word-chips">${getWords(d).slice(0,3).map(w=>`<button type="button" class="word-chip word-chip-audio" data-action="speak-word" data-id="${w.id}" aria-label="播放 ${esc(w.word)} 的发音">${esc(w.word)} ${icon('listening')}</button>`).join('')}</div><button class="btn small" data-action="lesson" data-day="${d.id}" data-skill="reading">进入故事 ${icon('arrow')}</button></article>`).join('')}</div>`;}
const sources=[{name:'Listening · 家具信息填空',type:'IELTS 官方公开样题 · 免费',desc:'在官方播放器中听原始录音并完成笔记填空。完成后回到这里记录结果。',url:'https://ielts.inspera.com/player/?assessmentRunId=189696078&context=exam',fallback:'https://ielts.org/take-a-test/preparation-resources/sample-test-questions/academic-test'},{name:'Reading · True / False / Not Given',type:'IELTS Academic 官方公开样题 · 免费',desc:'用官方阅读样题练习区分原文矛盾与信息未提及。不是未经核实的考场回忆题。',url:'https://ielts.inspera.com/player/?assessmentRunId=189698592&context=exam',fallback:'https://ielts.org/take-a-test/preparation-resources/sample-test-questions/academic-test'},{name:'Writing · Task 2',type:'IELTS 官方公开样题 · 免费',desc:'查看原始题目与官方提供的写作资源。完整 Task 2 训练需单独安排约 40 分钟。',url:'https://ielts.inspera.com/player/?assessmentRunId=189733431&context=exam',fallback:'https://ielts.org/take-a-test/preparation-resources/sample-test-questions/academic-test'},{name:'General Training · 阅读与写作',type:'IELTS 官方公开样题 · 免费',desc:'工作与移民方向的官方练习入口。最终选择 Academic 或 General Training，要以接收机构要求为准。',url:'https://ielts.org/take-a-test/preparation-resources/sample-test-questions/general-training-test'},{name:'Cambridge IELTS 20 Academic',type:'剑桥正版真题集 · 需要另行购买',desc:'出版社提供 4 套 authentic practice tests，配套音频、答案和写作资源。站内提供正版入口与成绩记录，不转载整套付费试卷。',url:'https://shop.cambridge.org/english/product/2700250101'},{name:'IELTS · 评分标准',type:'官方评分说明 · 免费',desc:'了解四项能力如何评估。站内练习准确率不直接换算为 IELTS 分数。',url:'https://ielts.org/take-a-test/your-results/ielts-scoring-in-detail'}];
function getOfficialRecords(){try{const value=JSON.parse(E.getDraft('official-records')||'[]');return Array.isArray(value)?value.filter(r=>r&&typeof r==='object'&&['name','skill','result','note','date'].every(k=>typeof r[k]==='string'&&r[k].length<1000)).slice(-100):[];}catch{return[];}}
function renderOfficial(){const records=getOfficialRecords();return heading('官方练习资源','官方公开样题、剑桥正版真题资源，与站内原创训练明确区分。','')+`<section class="hero" style="min-height:220px"><div class="hero-copy"><span class="tiny-label">IELTS.ORG · OFFICIAL SPEAKING SAMPLE</span><h2 style="font-size:27px">一件对你重要的物品。</h2><p>今天就做一题官方 Part 2 公开样题。<br>1 分钟准备，1–2 分钟表达，然后回听。</p><button class="btn primary" data-action="official-speaking">在站内录音练习 ${icon('arrow')}</button></div><div class="hero-art"><div class="arch"></div><div class="hero-timer"><strong>02</strong><span>SPEAKING PART TWO</span></div></div></section><div class="notice">官方样题不等同于某一场历年试卷；剑桥真题集提供官方 authentic practice tests。播放器可能受浏览器或网络限制，届时使用资源页入口。本站没有将原创题标为考试真题。</div><div class="source-list">${sources.map(s=>`<article class="source-card"><div class="eyebrow">${esc(s.type)}</div><h3>${esc(s.name)}</h3><p>${esc(s.desc)}</p><div class="inline-row"><a class="btn small" href="${s.url}" target="_blank" rel="noopener noreferrer">打开官方资源 ↗</a>${s.fallback?`<a class="inline-source" href="${s.fallback}" target="_blank" rel="noopener noreferrer">资源页备用入口</a>`:''}</div></article>`).join('')}</div><section class="panel" style="margin-top:24px"><h3>把官方练习也记下来</h3><form id="official-record-form"><div class="settings-grid"><div><label class="field-label" for="official-name">来源 / 卷册 / 题目</label><input id="official-name" name="name" class="field" required maxlength="160" placeholder="例如 IELTS 官方 Listening 填空"></div><div><label class="field-label" for="official-skill">技能</label><select id="official-skill" name="skill"><option>Listening</option><option>Reading</option><option>Writing</option><option>Speaking</option></select></div><div><label class="field-label" for="official-result">结果（可写正确题数或教师反馈）</label><input id="official-result" name="result" class="field" required maxlength="200" placeholder="例如 6/8；拼写和单复数还需复查"></div><div><label class="field-label" for="official-note">下次要改进什么？</label><input id="official-note" name="note" class="field" maxlength="300" placeholder="记录一个具体行动"></div></div><button class="btn primary" style="margin-top:18px" type="submit">保存练习记录</button></form>${records.slice().reverse().slice(0,10).map(r=>`<div class="history-item"><strong>${esc(r.name)}</strong> <span class="muted">${esc(r.date)} · ${esc(r.skill)}</span><p>${esc(r.result)} ${esc(r.note)}</p></div>`).join('')}</section>`;}
function renderOfficialSpeaking(){return heading('官方 Speaking · Part 2','IELTS 官方公开样题 · 题干原文；下方提示为中文概括。','',`<button class="btn small" data-action="nav" data-view="official">← 官方资源</button>`)+speakingWorkspace({title:'Something important to you',prompt:'Describe something you own which is very important to you.',cues:['说明它从哪里来、你拥有它多久。','介绍它的用途，并解释它为什么重要。','准备 1 分钟，表达 1–2 分钟。']},'official-speaking',true);}
function allQuestions(){return [...grammar,...days.flatMap(d=>[...d.reading.questions,...d.listening.questions])];}
function renderProgress(){const st=E.getState(),stats=E.stats(),all=st.attempts.filter(a=>a.skill!=='vocabulary-self');const latest=new Map();all.forEach(a=>latest.set(a.questionId,a));const mistakes=[...latest.values()].filter(a=>!a.correct);const dates=Array.from({length:7},(_,i)=>E.addDays(today(),i-6));return heading('学习记录','查看练习数量、正确率和错题。','')+`<div class="stat-row"><div class="stat-card"><div><div class="stat-number">${stats.streak}<small> 天</small></div><p>连续学习</p></div></div><div class="stat-card"><div><div class="stat-number">${all.length}</div><p>累计客观题作答次数</p></div></div><div class="stat-card"><div><div class="stat-number">${all.length?Math.round(all.filter(a=>a.correct).length/all.length*100)+'%':'—'}</div><p>练习准确率 · 非 IELTS 分数</p></div></div></div><div class="training-layout"><section class="panel"><h3>最近 7 天答题量</h3><div class="bars">${dates.map(date=>{const n=st.days[date]?.answers?Object.keys(st.days[date].answers).length:0,max=Math.max(1,...dates.map(x=>Object.keys(st.days[x]?.answers||{}).length));return `<div class="bar-col"><span>${n}</span><div class="bar" style="height:${Math.max(3,n/max*80)}px"></div><span>${shortDate(date)}</span></div>`;}).join('')}</div><p class="small-text muted">按每天作答过的题目数量统计，重复提交同一道题不增加柱高。</p></section><section class="panel"><h3>技能练习分布</h3>${['listening','reading','grammar','vocabulary'].map(skill=>{const a=all.filter(x=>x.skill===skill);return `<div class="history-item inline-row between"><span>${names[skill]||'词汇 Vocabulary'}</span><span class="muted">${a.length} 次 · ${a.length?Math.round(a.filter(x=>x.correct).length/a.length*100)+'%':'尚未练习'}</span></div>`;}).join('')}<p class="small-text muted">写作、口语记录以完成检查和自我复盘为准，不自动预测分数。</p></section></div><section class="panel"><div class="section-head" style="margin-top:0"><h3>错题</h3><span>${mistakes.length} 道待巩固</span></div>${mistakes.length?mistakes.slice(-20).reverse().map(a=>{const q=allQuestions().find(q=>q.id===a.questionId),w=words.find(w=>'vocab:'+w.id===a.questionId||'vocab-'+w.id===a.questionId);return `<div class="history-item"><strong>${esc(q?.prompt||w?.meaning||a.questionId)}</strong><p>你的答案：${esc(a.given)} · 正确答案：${esc(q?.answer||w?.word||'请回到题目核对')}</p><p>${esc(q?.explanation||'回到词汇复习，用新形式再次回忆。')}</p>${q?`<button class="text-link" data-action="retry-one" data-id="${esc(q.id)}">重新作答 ↗</button>`:`<button class="text-link" data-action="nav" data-view="memory">查看词汇 ↗</button>`}</div>`;}).join(''):empty('这里暂时没有待巩固题目','完成练习后，最近一次答错的题目会出现在这里。')}</section>`;}
function renderSettings(){const s=E.getState().settings;return heading('学习设置','设置考试目标，导入或导出学习备份。','')+`<section class="panel"><h3>当前学习档案</h3><form id="settings-form"><div class="settings-grid"><div><label class="field-label" for="target">目标总分</label><select name="target" id="target">${[6,6.5,7,7.5,8,8.5,9].map(n=>`<option value="${n}" ${n===s.target?'selected':''}>${n}</option>`).join('')}</select></div><div><label class="field-label" for="test-type">考试类型</label><select name="testType" id="test-type"><option value="undecided" ${s.testType==='undecided'?'selected':''}>尚未确定</option><option value="academic" ${s.testType==='academic'?'selected':''}>Academic</option><option value="general" ${s.testType==='general'?'selected':''}>General Training</option></select></div></div><p class="small-text muted">计划为每天 60 分钟。当前训练以共通基础能力为主；类型设置用于学习档案，不会把原创短篇变成完整考试题。</p><button class="btn primary" type="submit">保存设置</button></form></section><section class="panel"><h3>保存与备份</h3><p class="small-text muted">答题、词汇复习与草稿保存在当前设备的浏览器中，不会跨设备自动同步。换浏览器或清理站点数据前，请导出备份；口语录音需在录音页面单独下载。</p><div class="inline-row"><button class="btn primary" data-action="export">导出学习备份</button><label class="btn secondary" for="import-file">导入学习备份</label><input id="import-file" type="file" accept="application/json,.json" class="sr-only"></div><p class="small-text muted">导入会替换当前浏览器的学习记录。导入前将先下载当前备份。</p></section><section class="panel"><h3>内容与学习方法</h3><p class="small-text">内置 14 天原创学习单元、${words.length} 个词汇、${grammar.length} 道语法题和四项训练。故事为原创教学内容；基础听力采用英语合成语音。官方样题与正版真题资源有独立来源标识。</p><p class="small-text">学习日期采用北京时间。默认 6 个新词；基于前一天回忆效果调节至 3–12 个，积压时暂停新词。重复当天练习不会提前提升间隔。</p><a class="inline-source" target="_blank" rel="noopener noreferrer" href="https://www.psychologicalscience.org/journals/pspi/1529100612453266/">间隔学习与主动回忆的研究依据 ↗</a></section>`;}
function download(content,name,type='application/json'){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportBackup(){download(E.exportData(),`ember-study-${today()}.json`);toast('学习备份已导出，录音请单独下载');}
let wordAudioButton=null,wordPlaybackToken=0;
function wordAudioControls(w){return `<div class="word-audio-controls"><button type="button" class="btn small secondary" data-action="speak-word" data-id="${w.id}" aria-label="播放 ${esc(w.word)} 的发音">${icon('listening')} 听发音</button><button type="button" class="btn small secondary" data-action="speak-word" data-id="${w.id}" data-rate="0.75" aria-label="慢速播放 ${esc(w.word)}">慢速跟读</button><span class="audio-origin">美式合成发音</span></div>`;}
function stopWordAudio(){
  wordPlaybackToken++;
  const player=$('#word-audio');
  if(player){player.pause();player.onended=null;player.onerror=null;player.onplaying=null;}
  if(wordAudioButton){wordAudioButton.removeAttribute('data-playing');wordAudioButton.setAttribute('aria-pressed','false');}
  wordAudioButton=null;
}
async function playWordAudio(id,button){
  const w=words.find(w=>w.id===id),player=$('#word-audio');if(!w||!player)return;
  if(wordAudioButton===button&&!player.paused){stopWordAudio();return;}
  stopSpeech();$('#lesson-audio')?.pause();
  const token=wordPlaybackToken;wordAudioButton=button;
  player.src='audio/words/'+encodeURIComponent(w.id)+'.wav';
  player.playbackRate=button.dataset.rate==='0.75'?.75:1;
  player.preservesPitch=true;
  button.setAttribute('aria-pressed','true');button.setAttribute('data-playing','true');
  let failed=false;
  const fail=()=>{if(failed||token!==wordPlaybackToken)return;failed=true;stopWordAudio();toast('单词音频暂时无法播放，正在尝试备用朗读');speak(w.word);};
  player.onended=()=>{if(token===wordPlaybackToken)stopWordAudio();};
  player.onerror=fail;
  try{await player.play();}catch(error){
    if(token!==wordPlaybackToken||error.name==='AbortError')return;
    if(error.name==='NotAllowedError'){stopWordAudio();toast('请点击发音按钮播放；如果仍无声，请检查浏览器声音权限。');}
    else fail();
  }
}
function stopSpeech(){stopWordAudio();if('speechSynthesis'in window)window.speechSynthesis.cancel();}
function speak(text){if(!('speechSynthesis'in window)){toast('当前浏览器不支持朗读，请使用音频播放器');return;}stopSpeech();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';const voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang==='en-US')||voices.find(v=>v.lang.startsWith('en'));if(voice)u.voice=voice;u.rate=.92;u.onerror=()=>toast('朗读未启动，请检查浏览器语音功能或播放预制音频');speechSynthesis.speak(u);}
function openAudioDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('当前浏览器不支持保存录音'));const request=indexedDB.open('ember-audio',1);request.onupgradeneeded=()=>request.result.createObjectStore('recordings');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function saveRecording(key,blob){const db=await openAudioDB();return new Promise((resolve,reject)=>{const tx=db.transaction('recordings','readwrite');tx.objectStore('recordings').put({blob,at:new Date().toISOString()},key);tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error);};});}
async function loadRecording(key){lastRecordBlob=null;try{const db=await openAudioDB();const item=await new Promise((resolve,reject)=>{const req=db.transaction('recordings').objectStore('recordings').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});db.close();if(activeRecordKey!==key)return;if(item){lastRecordBlob=item.blob;showPlayback(item.blob);$('#record-status').textContent='上次录音已恢复 · '+new Date(item.at).toLocaleDateString('zh-CN');}}catch{if($('#record-status'))$('#record-status').textContent='可录音回放；持久保存不可用时请下载。';}}
function showPlayback(blob){if(!$('#record-playback'))return;if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(blob);$('#record-playback').innerHTML=`<audio controls src="${recordUrl}"></audio><button class="btn small secondary" data-action="download-recording">下载本次录音</button>`;}
async function startRecording(key){if(recorder?.state==='recording'){stopRecording();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('当前浏览器不支持录音。请在 Chrome / Edge 的 HTTPS 页面打开，或朗读后填写复盘。');return;}try{mediaStream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];recorder=new MediaRecorder(mediaStream);activeRecordKey=key;const captureKey=key;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=async()=>{const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});lastRecordBlob=blob;showPlayback(blob);try{await saveRecording(captureKey,blob);if($('#record-status'))$('#record-status').textContent='录音已保存。回听后，记录一处改进。';}catch{toast('录音可回放，但本机保存失败，请立即下载');}mediaStream?.getTracks().forEach(t=>t.stop());};recorder.start();recordStarted=Date.now();$('#record-button').classList.add('recording');$('#record-button').setAttribute('aria-label','停止录音');$('#record-status').textContent='正在录音 · 再次点击结束';recordTick=setInterval(()=>{const seconds=Math.floor((Date.now()-recordStarted)/1000);if($('#record-clock'))$('#record-clock').textContent=formatTime(seconds);if(seconds>=180)stopRecording();},300);}catch(e){toast(e.name==='NotAllowedError'?'麦克风未获允许。可在浏览器地址栏开启权限，或先自行朗读。':'无法启动麦克风：'+e.message);mediaStream?.getTracks().forEach(t=>t.stop());}}
function stopRecording(){clearInterval(recordTick);if(recorder?.state==='recording')recorder.stop();$('#record-button')?.classList.remove('recording');$('#record-button')?.setAttribute('aria-label','开始录音');}
function formatTime(s){s=Math.max(0,Math.floor(s));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function countSpeaking(seconds,label){clearInterval(speakCountdown);const start=Date.now();const update=()=>{const left=Math.max(0,seconds-Math.floor((Date.now()-start)/1000));if($('#speaking-countdown'))$('#speaking-countdown').textContent=label+' '+formatTime(left);if(!left){clearInterval(speakCountdown);toast(label+'结束');}};update();speakCountdown=setInterval(update,300);}
function toggleTimer(){timerRunning=!timerRunning;$('#timer-toggle').classList.toggle('running',timerRunning);if(timerRunning){if(timerSeconds>=3600){toast('今天已计满 60 分钟，可以继续自由练习');timerRunning=false;$('#timer-toggle').classList.remove('running');return;}timerStart=Date.now();timerTick=setInterval(()=>{if(today()!==timerDate){timerDate=today();timerSeconds=0;}const elapsed=Math.floor((Date.now()-timerStart)/1000);if(elapsed<1)return;timerSeconds+=elapsed;timerStart+=elapsed*1000;E.addMinutes(elapsed/60);$('#timer-time').textContent=formatTime(3600-timerSeconds);if(timerSeconds>=3600){toggleTimer();toast('今日学习计时已满 60 分钟。');}},1000);}else clearInterval(timerTick);}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{switch(a){case'menu':$('#sidebar').classList.toggle('open');break;case'nav':navigate(b.dataset.view);break;case'select-day':navigate('today',b.dataset.day);break;case'lesson':navigate('lesson',b.dataset.day,b.dataset.skill);break;case'task':if(b.dataset.skill==='review')beginReview();else navigate('lesson',null,b.dataset.skill);break;case'start-day':{const s=skills.find(x=>!done(x));if(!s){toast('这一天的六项任务已完成，可以复盘或查看下一天');return;}if(!timerRunning)toggleTimer();if(s==='review')beginReview();else navigate('lesson',null,s);break;}case'timer':toggleTimer();break;case'bank-filter':bankFilter=b.dataset.filter;render();break;case'retry-quiz':render();break;case'writing-feedback':writingFeedback();break;case'finish-writing':{if(wordCount($('#writing-draft').value)<selected().writing.minWords){toast('请先达到本次建议词数，再完成自查');return;}if($$('.writing-check').some(x=>!x.checked)){toast('请完成写作自查清单');return;}complete('writing');navigate('today');break;}case'finish-speaking':{if(!$('#reflection').value.trim()||$$('.speaking-check').some(x=>!x.checked)){toast('请填写一处改进，并完成回听自查');return;}if(activeSkill==='official-speaking')E.complete('official:speaking');else complete('speaking');navigate(activeSkill==='official-speaking'?'official':'today');break;}case'begin-review':beginReview();break;case'close-word-card':b.closest('details').open=false;$('#review-answer')?.focus();break;case'next-word':reviewIndex++;reviewAnswered=false;render();break;case'rate-word':rateWord(b.dataset.correct==='true');break;case'speak-word':playWordAudio(b.dataset.id,b);break;case'speak-listening':speak(selected().listening.transcript);break;case'stop-speech':stopSpeech();break;case'word-detail':{const w=words.find(w=>w.id===b.dataset.id);$('#main').innerHTML=heading(w.word,w.meaning,'',`<button class="btn small" data-action="nav" data-view="memory">← 词汇列表</button>`)+`<section class="panel review-card"><div class="word-display">${esc(w.word)}</div><div class="phonetic">${esc(w.phonetic)} · ${esc(w.pos)}</div><p class="word-meaning">${esc(w.meaning)}</p><p class="article">${esc(w.example)}</p>${wordAudioControls(w)}<details class="details"><summary>造句练习</summary><textarea class="writing-box" style="min-height:120px" data-draft="word-sentence-${w.id}" aria-label="词汇造句">${esc(E.getDraft('word-sentence-'+w.id))}</textarea></details></section>`;window.scrollTo(0,0);break;}case'official-speaking':navigate('lesson',null,'official-speaking');break;case'record':await startRecording(b.dataset.key);break;case'download-recording':if(lastRecordBlob)download(lastRecordBlob,`${activeRecordKey}-${today()}.${lastRecordBlob.type.includes('mp4')?'m4a':'webm'}`);break;case'prep-timer':countSpeaking(60,'准备');break;case'speak-timer':countSpeaking(120,'表达');break;case'export':exportBackup();break;case'retry-one':{const id=b.dataset.id;let d=days.find(x=>x.reading.questions.some(q=>q.id===id)||x.listening.questions.some(q=>q.id===id));if(d){navigate('lesson',d.id,d.reading.questions.some(q=>q.id===id)?'reading':'listening');}else{view='lesson';activeSkill='grammar';updateNav();$('#main').innerHTML=heading('错题重练','提交后会更新错题记录。','')+`<section class="panel">${quizHTML([grammar.find(q=>q.id===id)],'grammar').replace('id="quiz-form"','id="quiz-form" data-review-only="true"')}</section>`;}break;}}}catch(err){toast('操作未完成：'+err.message);console.error(err);}});
document.addEventListener('input',e=>{if(e.target.dataset.draft){E.setDraft(e.target.dataset.draft,e.target.value);if(e.target.id==='writing-draft'){updateWordCount();$('#draft-status').textContent=E.getLastError()?'保存失败，请导出备份':'已自动保存';}}if(e.target.id==='word-search')filterWords();});
document.addEventListener('change',async e=>{if(e.target.id==='word-filter')filterWords();if(e.target.id==='audio-speed'&&$('#lesson-audio'))$('#lesson-audio').playbackRate=Number(e.target.value);if(e.target.id==='import-file'){const f=e.target.files[0];if(!f)return;if(f.size>8*1024*1024){toast('备份过大，请选择本站导出的 JSON 文件');return;}try{const raw=await f.text();JSON.parse(raw);if(!confirm('导入将替换当前学习记录。继续前会先下载一份当前备份，是否继续？'))return;exportBackup();E.importData(raw);selectedDay=Math.min(14,dayIndex());toast('学习记录已恢复');render();}catch(err){toast('无法导入：'+err.message);}e.target.value='';}});
document.addEventListener('submit',e=>{e.preventDefault();try{if(e.target.id==='quiz-form')submitQuiz(e.target);if(e.target.id==='review-form')submitReview();if(e.target.id==='settings-form'){const f=new FormData(e.target);E.getState().settings.target=Number(f.get('target'));E.getState().settings.testType=f.get('testType');E.save();toast(E.getLastError()?'保存失败，请导出当前备份':'设置已保存');showStorageError();$('.profile small').textContent='2027 · 目标 IELTS '+E.getState().settings.target;}if(e.target.id==='official-record-form'){const f=new FormData(e.target),r=getOfficialRecords();r.push({name:String(f.get('name')),skill:String(f.get('skill')),result:String(f.get('result')),note:String(f.get('note')),date:today()});E.setDraft('official-records',JSON.stringify(r.slice(-100)));E.complete('official:'+f.get('skill'));toast('官方练习记录已保存');render();}}catch(err){toast('保存未完成：'+err.message);}});
window.addEventListener('beforeunload',()=>{if(mediaStream)mediaStream.getTracks().forEach(t=>t.stop());stopSpeech();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&timerRunning)toggleTimer();});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(['today','plan','bank','memory','stories','official','progress','settings'].includes(h))navigate(h);});
const initial=location.hash.slice(1);if(['today','plan','bank','memory','stories','official','progress','settings'].includes(initial))view=initial;
$('.profile small').textContent='2027 · 目标 IELTS '+E.getState().settings.target;$('#timer-time').textContent=formatTime(3600-timerSeconds);render();
})();
